code.cpp:
class Solution {
public:
    TreeNode* insertIntoMaxTree(TreeNode* root, int val) {
        TreeNode* node = new TreeNode(val);
        if (root == nullptr) return node;
        if (val > root->val) {
            node->left = root;
            return node;
        }
        TreeNode* curr = root;
        while (curr->right != nullptr && curr->right->val > val) {
            curr = curr->right;
        }
        node->left = curr->right;
        curr->right = node;
        return root;
    }
};
